### PersonService.java
```java
package com.example.crud.service;

import com.example.crud.model.Person;
import com.example.crud.repository.PersonRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
public class PersonService {
    private final PersonRepository repo;
    public PersonService(PersonRepository repo) { this.repo = repo; }

    public List<Person> findAll() { return repo.findAll(); }

    public Person findById(Long id) {
        return repo.findById(id).orElseThrow(() -> new IllegalArgumentException("ID não encontrado"));
    }

    @Transactional
    public Person save(Person p) { return repo.save(p); }

    @Transactional
    public void delete(Long id) { repo.deleteById(id); }
}
```

### PersonController.java
```java
package com.example.crud.controller;

import com.example.crud.model.Person;
import com.example.crud.service.PersonService;
import jakarta.validation.Valid;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;

@Controller
@RequestMapping("/persons")
public class PersonController {
    private final PersonService service;
    public PersonController(PersonService service) { this.service = service; }

    @GetMapping
    public String list(Model m) {
        m.addAttribute("persons", service.findAll());
        return "list";
    }

    @GetMapping("/new")
    public String form(Model m) {
        m.addAttribute("person", new Person());
        return "form";
    }

    @PostMapping
    public String save(@Valid @ModelAttribute Person person,
                       BindingResult br, Model m) {
        if (br.hasErrors()) return "form";
        service.save(person);
        return "redirect:/persons";
    }

    @GetMapping("/edit/{id}")
    public String edit(@PathVariable Long id, Model m) {
        m.addAttribute("person", service.findById(id));
        return "form";
    }

    @PostMapping("/delete/{id}")
    public String delete(@PathVariable Long id) {
        service.delete(id);
        return "redirect:/persons";
    }
}
```

