### controller/ProdutoController.java
```java
package com.example.crud.controller;

import com.example.crud.model.Produto;
import com.example.crud.repository.ProdutoRepository;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;

import jakarta.validation.Valid;
import java.util.List;

@Controller
@RequestMapping("/produtos")
public class ProdutoController {

    private final ProdutoRepository repo;

    public ProdutoController(ProdutoRepository repo) {
        this.repo = repo;
    }

    @GetMapping
    public String list(Model model) {
        List<Produto> produtos = repo.findAll();
        model.addAttribute("produtos", produtos);
        model.addAttribute("produto", new Produto());
        return "list";
    }

    @PostMapping
    public String save(@Valid @ModelAttribute Produto produto,
                       BindingResult result,
                       Model model) {
        if (result.hasErrors()) {
            model.addAttribute("produtos", repo.findAll());
            return "list";
        }
        repo.save(produto);
        return "redirect:/produtos";
    }

    @GetMapping("/edit/{id}")
    public String edit(@PathVariable Long id, Model model) {
        Produto p = repo.findById(id).orElseThrow();
        model.addAttribute("produto", p);
        model.addAttribute("produtos", repo.findAll());
        return "list";
    }

    @GetMapping("/delete/{id}")
    public String delete(@PathVariable Long id) {
        repo.deleteById(id);
        return "redirect:/produtos";
    }
}
```

